window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch10"]={"id":"ch10","title":"第六章(一) 细胞信号转导","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"信号分子 · 受体 · 第二信使","modules":[{"i":0,"name":"绪论 · 概览","slides":[{"i":0,"sec":"","title":"第6讲 细胞信号转导/细胞通讯","notes":"细胞通讯 (cell communication)\n多细胞生物，细胞间或细胞内精确、高效接收信息，\n并级联放大，引起快速的细胞生理反应or 基因活动，\n使生物体对外界环境刺激作出相应的反应。\n【结合课本/笔记】总趋势●细胞生物学与分子生物学(包括分子遗传学与生物化学) 相互渗透与交融是总的发展趋势。重点领域●染色体DNA与蛋白质相互作用关系—主要是非组蛋白对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装","page":1,"level":"掌握","img":"assets/img/ch10/p001.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":1,"sec":"","title":"细胞通讯的基本过程：","notes":"●信号分子的合成：主要来源内分泌细胞\n●信号分子从合成细胞释放到周围环境；\n●信号分子向靶细胞运输：血液循环为主\nμ靶细胞对信号分子识别检测：质膜、胞内受体特异选择；\n●靶细胞对细胞外信号转导，转化为胞内信号；\n●胞内信号作用于效应分子，逐级放大的级联反应，引起细胞\n代谢、生长、基因表达等方面的变化；\n●信号分子完成任务后，信号的解除灭活，终止细胞应答。","page":2,"level":"掌握","img":"assets/img/ch10/p002.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":2,"sec":"","title":"Extracellular signals can act slowly or rapidly to change the","notes":"behavior of a target cell\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页主题为细胞外信号（extracellular signals）改变靶细胞（target cell）行为，作用可快可慢。核心概念：同一类胞外信号作用于靶细胞后，有的在数秒内引起快速反应，如离子通道开放、代谢酶活性改变；有的需数小时甚至数天，如调控基因表达、促进增殖分化。翟中和《细胞生物学》第九章据此区分快、慢信号通路。","page":3,"level":"掌握","img":"assets/img/ch10/p003.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":3,"sec":"","title":"胞内信号分子可以传递、放大、 受体与信号分子空间结构的","notes":"再整合和分流输入的信号。   互补性是二者特异结合的主\n要因素，但并不是简单的一\n对一关系。\n可能有不同受体，引起不同生理\n学效应。如乙酰胆碱(心肌细胞、骨\n骼肌、唾液腺细胞)\n同胞外信号，产生相同效应。\n如肝脏细胞肾上腺素、胰高血糖\n素受体各自被对应信号激活后，都促进\n糖原分解升高血糖。","page":4,"level":"掌握","img":"assets/img/ch10/p004.jpg","anim":null,"fig":null,"points":["同一种化学信号在不同细胞中","同一个细胞上不同受体应答不"],"check":{"q":"关于「胞内信号分子可以传递、放大、 受体与信号分子空间…」，下列说法正确的是（　）","o":["A. NO acts only locally because it has a short half-life (about","B. G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","C. 绝大多数受体都是蛋白质且多为糖蛋白，","D. 同一种化学信号在不同细胞中"],"a":"D","e":"本页要点：同一种化学信号在不同细胞中"},"cards":null},{"i":4,"sec":"","title":"同一信号分子(eg. 乙酰胆碱)能引起不同靶细","notes":"胞的不同反应。\n心肌细胞：降低收缩频率\n唾液腺细胞：分泌唾液\n骨骼肌细胞：肌肉收缩","page":5,"level":"掌握","img":"assets/img/ch10/p005.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_mcq_7","mod":"绪论 · 概览","modI":0,"q":"霍乱杆菌引起急性腹泻是由于（              ）。","o":["A．G 蛋白持续激活","B．G 蛋白不能被激活","C．受体封闭","D．蛋白激酶 PKC 功能异常","E．蛋白激酶 PKA 异常"],"a":"A","e":"","kp":"ch10_s0_0"}],"judge":[{"id":"ch10_judge_7","modI":0,"q":"ras 是一个癌基因。（  ）","a":"错","e":"ras 是一个原癌基因，如果带有使其始终处于活化状态的突变，才会变成癌基因。","kp":"ch10_s0_0"},{"id":"ch10_judge_8","modI":0,"q":"乙酰胆碱对一个动物的不同细胞有不同的效应，而且它和不同细胞上的不同受体分子相 结合。（      ）","a":"对","e":"比如，乙酰胆碱通过结合一种 G 蛋白耦联受体而减弱心肌细胞的搏动；通过结合 另一不同的乙酰胆碱受体而刺激骨骼肌细胞的收缩。这种受体是一种配体门控离子通道。","kp":"ch10_s0_3"}],"fill":[{"id":"ch10_fill_14","modI":0,"q":"自身免疫性受体病是由于______。","a":"机体产生抗自身受体的抗体，与受体结合后使受体失去功能或改变作用方向查看答 案","kp":"ch10_s0_0"}],"short":[{"id":"ch10_short_1","modI":0,"q":"简述细胞通讯的方式。","a":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","kp":"ch10_s0_1"},{"id":"ch10_short_3","modI":0,"q":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","a":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","kp":"ch10_s0_0"},{"id":"ch10_short_6","modI":0,"q":"简述日咳产生的细胞学原因。","a":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","kp":"ch10_s0_0"},{"id":"ch10_short_12","modI":0,"q":"细胞信号转导的复杂性主要表现在哪几个方面？","a":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","kp":"ch10_s0_0"},{"id":"ch10_short_13","modI":0,"q":"试述参与细胞信号转导的细胞膜受体的种类与特点。","a":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","kp":"ch10_s0_0"}],"calc":[],"term":[]},{"i":1,"name":"一、信号分子","slides":[{"i":5,"sec":"一、信号分子","title":"一、信号分子","notes":"指生物体内的某些化学分子，主要用来在细胞间和细\n胞内传递信息，如激素、神经递质、生长因子等，其\n唯一功能是与细胞受体结合并传递信息。\n●水溶性信使－细胞表面受体\n●脂溶性信号－胞质或核受体\n例如：\n（占脊椎动物细胞80％，细胞质膜受体）\n腺素和甲状腺素\n【结合课本/笔记】第二节 细胞通讯与信号传递●细胞通讯与细胞识别●细胞的信号分子与受体●通过细胞内受体介导的信号传递●通过细胞表面受体介导的信号跨膜传递●由细胞表面整合蛋白介导的信号传递●细胞信号传递的基本特征与蛋白激酶的网络整合信息","page":6,"level":"掌握","img":"assets/img/ch10/p006.jpg","anim":null,"fig":null,"points":["蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","氨基酸衍生物：酪氨酸衍生的小分子激素，如肾上","类固醇激素(不溶于水，作用于细胞内受体)","可溶解的气体分子等"],"check":{"q":"关于「信号分子」，下列说法正确的是（　）","o":["A. 两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","B. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","C. 既有信号结合位点，本身又是离子通道的一部分","D. NO acts only locally because it has a short half-life (about"],"a":"B","e":"本页要点：蛋白质与多肽激素：肽链长度3-几百个氨基酸残基"},"cards":null}],"mcq":[{"id":"ch10_mcq_3","mod":"一、信号分子","modI":1,"q":"对于由整联蛋白介导的信号传递，下列哪项说法错误？（            ）","o":["A．胞外配体主要为细胞外基质成分，如纤连蛋白等","B．整联蛋白与胞外配体的相互作用只产生一种胞内信号，即胞内 Ca2+浓度增加","C．当胞外配体与整联蛋白结合，可导致分子开关蛋白 Rho 蛋白激活","D．最终作用是与细胞增殖相关的基因被激活，细胞周期相关蛋白合成"],"a":"B","e":"整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞质基质，肌 醇第二信使的合成，胞内酪氨酸残基的磷酸化等。","kp":"ch10_s1_5"}],"judge":[{"id":"ch10_judge_10","modI":1,"q":"细胞外信号都是通过细胞表面受体来进行跨膜信号传递的。（                    ）","a":"错","e":"有的脂溶性的信号分子可以跨膜进入细胞与胞内受体结合。","kp":"ch10_s1_5"}],"fill":[{"id":"ch10_fill_6","modI":1,"q":"细胞的信号传递是______、______、______、______的______过程。","a":"多通路；多环节；多层次；高度复杂可控","kp":"ch10_s1_5"},{"id":"ch10_fill_8","modI":1,"q":"通过黏合斑由整联蛋白介导的信号传递通路有两条：______和______。","a":"由细胞表面到细胞核的信号通路；由细胞表面到细胞质核糖体的信号通路","kp":"ch10_s1_5"},{"id":"ch10_fill_12","modI":1,"q":"动物细胞间通讯连接的主要方式是______，植物细胞的通讯连接方式是通过______。","a":"间隙连接；胞间连丝","kp":"ch10_s1_5"}],"short":[{"id":"ch10_short_11","modI":1,"q":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","a":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","kp":"ch10_s1_5"}],"calc":[],"term":[]},{"i":2,"name":"1.1 化学信号","slides":[{"i":6,"sec":"1.1    化学信号","title":"1.1    化学信号","notes":"内分泌激素：由内分泌细胞产生，分泌到血液中，广泛地运送\n到生物体全身－距离最远。如类固醇激素、胰岛素、肾上腺\n素、甲状腺素等。\n旁分泌(局部介质)：只作用于周围局部细胞，分泌出来后停留\n在分泌细胞周围的细胞外液体中。eg.生长因子、淋巴因子、\n前列腺素、NO。\n神经递质/化学突触：神经末梢释放出来的信号，因扩散距离有\n限，神经突触必须与靶细胞很近。如乙酰胆碱等，作用速度\n快、部位精确、维持时间短、与受体亲和力低。\n自分泌信号：信号发放细胞与靶细胞为同类或图一个细胞，常\n见于癌细胞。","page":7,"level":"掌握","img":"assets/img/ch10/p007.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":7,"sec":"1.1    化学信号","title":"化学信号","notes":"【结合课本/笔记】细胞通讯（cell communication）一个细胞发出的信息通过介质传递到另一个细胞产生相应的反应。细胞间的通讯对于多细胞生物体的发生和组织的构建，协调细胞的功能，控制细胞的生长、分裂、分化和凋亡是必须的。●细胞通讯方式：●分泌化学信号进行通讯●内分泌（endocrine）●旁分泌（paracrine）●自分泌（autocrine）●化学突触（chemical synapse）●接触性依赖的通讯细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白●间隙连接实现代谢偶联或电偶联","page":8,"level":"掌握","img":"assets/img/ch10/p008.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[{"id":"ch10_judge_1","modI":2,"q":"细胞间的通讯就是通过细胞间形成缝隙连接，是细胞质相互沟通而实现的。（              ）","a":"错","e":"间隙连接仅仅是细胞通讯的一种方式，细胞通讯还可以通过分泌化学信号以及细胞 直接接触而实现，而且这两种方式是相对较普遍的。","kp":"ch10_s2_7"}],"fill":[{"id":"ch10_fill_1","modI":2,"q":"生物体内的化学信号分子一般可以分为______和______两类。","a":"亲脂性的信号分子；亲水性的信号分子","kp":"ch10_s2_7"},{"id":"ch10_fill_17","modI":2,"q":"细胞分泌化学信号的作用方式可分为：________、________、________；通过化学突触 传递神经信号。","a":"自分泌；内分泌；旁分泌","kp":"ch10_s2_6"}],"short":[],"calc":[],"term":[{"id":"ch10_term_1","modI":2,"term":"细胞通讯（cell communication）。","def":"细胞通讯（cell communication）是指一个细胞发出的信号通过某种介质传递到另一细胞， 并使其产生相应的反应。细胞通讯在多细胞生物体的发生和组织的构建，协调细胞的功能， 控制细胞的生长和分裂中发挥了重要的作用。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_7","modI":2,"term":"signal transduction","def":"signal transduction 的中文名称是信号转导。信号转导是指一个细胞发出的信息，可通过 介质传递到另一个细胞并产生相应的反应的过程，是一种复杂的系统通讯活动及协助细胞的 活动。信号转导可以实现细胞间通讯，是协调多细胞生物细胞间功能、控制细胞的生长和分 裂、组织发生与形态建成所必需的关键过程。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_9","modI":2,"term":"细胞通讯","def":"细胞通讯是指一个细胞发出的信息通过介质（又称配体）传递到另一个靶细胞并与其相 应的受体相互作用，然后通过细胞信号转导产生靶细胞内一系列生理生化变化，最终表现为 靶细胞整体的生物学效应的过程。","kps":"","kp":"ch10_s2_7"}]},{"i":3,"name":"1.2 细胞内的信号分子","slides":[{"i":8,"sec":"1.2   细胞内的信号分子","title":"气体信号分子 如NO, CO等，可以自由扩散入细胞。","notes":"1.2   细胞内的信号分子\n第二信使(second messenger):\n靶细胞外信号(第一信使)如不能进入细胞，作用于\n细胞表面受体，产生靶细胞内信号(非蛋白类小分\n子)，其浓度变化(增/减)启动或调节细胞内稍晚出现\n的信号应答；具有携带传递和放大信号的功能。\n环腺苷酸(cAMP)、cGMP、磷脂酸肌醇 (IP3),\n二酰基甘油(DAG)、钙离子","page":9,"level":"掌握","img":"assets/img/ch10/p009.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":9,"sec":"1.2   细胞内的信号分子","title":"4 common intracellular second messengers","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：1.2 细胞内的信号分子 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n• 第二信使（second messengers）：细胞表面受体接受细胞外信号后转换而来的细胞内信号称为第二信使。细胞内有5种最重要的第二信使：cAMP、cGMP、1，2-二酰甘油、1，4，5-三磷酸肌醇、Ca2+等。\n\n【本页英文讲解】\n本页主题：4种常见的胞内第二信使（intracellular second messengers）。第二信使是胞外信号分子（第一信使）与受体结合后，在细胞内生成或释放的小分子，负责把信号放大并向下游传递。原文仅列出标题，未给出具体名称；按翟中和教材，常见者包括cAMP、cGMP、IP3（三磷酸肌醇）和Ca2+（钙离子）等。考点：第二信使的放大效应与可扩散性。","page":10,"level":"掌握","img":"assets/img/ch10/p010.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_mcq_1","mod":"1.2   细胞内的信号分子","modI":3,"q":"下列有关气体信号分子 NO 的说法，错误的是（          ）。","o":["A．在平滑肌细胞内，L 精氨酸在 NO 合酶催化作用下生成 NO","B．NO 通过增强可溶性鸟苷酸环化酶的活性，发挥作用","C．鸟苷酸环化酶催化 GTP 生成 cGMP，cGMP 介导蛋白质的磷酸化","D．NO 通过舒张血管平滑肌治疗心绞痛，NO 也参与大脑的学习记忆生理过程"],"a":"A","e":"血管内皮细胞和神经细胞是 NO 的生成细胞，NO 再经扩散进入平滑肌细胞发挥作 用。","kp":"ch10_s3_8"},{"id":"ch10_mcq_5","mod":"1.2   细胞内的信号分子","modI":3,"q":"动物细胞内引起储存 Ca2 释放的第二信使分子是（               ）。 ＋","o":["A．IP3","B．DAG","C．cAMP","D．cGMP"],"a":"A","e":"IP3（三磷酸肌醇）作为第二信使，从质膜扩散到细胞质，引起 Ca2 从内质网钙库 ＋   中释放出来，导致细胞内 Ca2 浓度瞬间增高，这一作用发生在几乎所有真核细胞中。 ＋","kp":"ch10_s3_8"}],"judge":[{"id":"ch10_judge_9","modI":3,"q":"NO 作为信号分子，它能使细胞内的 cAMP 水平升高。（              ）","a":"错","e":"NO 释放后可以激活其受体，从而刺激生成第二信使 cGMP，cGMP 的作用是通过 cGMP 依赖的蛋白激酶 G 的活化抑制肌动-肌球蛋白复合物信号通路，导致血管平滑肌的舒 张。","kp":"ch10_s3_8"}],"fill":[{"id":"ch10_fill_4","modI":3,"q":"在体内发现的第一个气体信号分子是______。","a":"NO","kp":"ch10_s3_8"},{"id":"ch10_fill_11","modI":3,"q":"NO 在胞外极不稳定，被氧化后以______的形式存在于细胞外液中。","a":"硝酸根或亚硝酸根","kp":"ch10_s3_8"}],"short":[],"calc":[],"term":[]},{"i":4,"name":"二、受体(receptor)","slides":[{"i":10,"sec":"二、受体(receptor)","title":"信号分子称为配体 (ligand)","notes":"二、受体(receptor)\n位于细胞膜表面或细胞内能识别和选择性结合某\n种配体信号的生物大分子，与配体结合后，产生化学\n或物理的信号，以启动一系列信号传递过程，最终表\n现为生物学效应。\nthat is shaped to recognize the signal molecule with high\nspecificity, helping to ensure that the receptor responds only\nto the appropritate signal and not to the many other\nsignaling molecules surrounding the cell.\nconcentrations(typically ×10-8M), and their receptors usually\nbind them with high affinity.\n【中文讲解·对照课本/考点】\n考点：二、受体(receptor) ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号分子（signaling molecules）：是指生物体内的某些化学分子，即非营养物，又非能源物质和结构物质，而且也不是酶，它们主要是用来在细胞间和细胞内传递信息，如激素、神经递质、生长因子等统称为信号分子，它们的唯一功能是同细胞受体结合，传递细胞信息。\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页区分两个基本概念。信号分子称为配体（ligand）。受体（receptor）是位于细胞膜表面或细胞内、能识别并选择性结合某种配体的生物大分子，结合后产生化学或物理信号，启动信号传递并产生生物学效应。受体结合位点能高特异性识别信号分子；许多信号分子浓度极低（约10⁻⁸ M），受体以高亲和力（high affinity）结合。考点：受体的特异性与高亲和力。","page":11,"level":"掌握","img":"assets/img/ch10/p011.jpg","anim":null,"fig":null,"points":["The binding site of the receptor has a complex structure","Many signal molecules act at very low"],"check":{"q":"关于「信号分子称为配体 (ligand)」，下列说法正确的是（　）","o":["A. G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","B. 绝大多数受体都是蛋白质且多为糖蛋白，","C. The binding site of the receptor has a complex structure","D. 异三聚体G蛋白：α, β, γ三亚基组成"],"a":"C","e":"本页要点：The binding site of the receptor has a complex structure"},"cards":null},{"i":11,"sec":"二、受体(receptor)","title":"受体是一类能够识别和选择性结合某种配体（信号分子）的大","notes":"分子；\n体。\n细胞内受体     细胞表面受体\n\n【读图讲解】\n本页讲受体及其分类。文字定义受体为能识别并选择性结合配体(信号分子)的大分子，绝大多数是蛋白质且多为糖蛋白，少数为糖脂(如霍乱毒素、百日咳毒素受体)，也有糖蛋白与糖脂组成的复合物(如促甲状腺素受体)。下方两图对比：左为细胞内受体，小分子疏水性信号分子经载体蛋白进入靶细胞，与胞内受体蛋白结合后作用于细胞核；右为细胞表面受体，亲水性信号分子不能过膜，只能与质膜上的受体蛋白结合。要点：信号分子性质决定受体所在位置。","page":12,"level":"掌握","img":"assets/img/ch10/p012.jpg","anim":null,"fig":null,"points":["绝大多数受体都是蛋白质且多为糖蛋白，","少数受体是糖脂（如霍乱毒素受体和百日咳毒素受体），","有的受体是糖蛋白和糖脂组成的复合物, 如促甲状腺素受"],"check":{"q":"关于「受体是一类能够识别和选择性结合某种配体（信号分子…」，下列说法正确的是（　）","o":["A. NO在神经细胞中产生，参与大脑的学习记忆的生理","B. The receptor activation stimulated by light causes a fall rather than …","C. 离子通道(K+, Na+等)","D. 绝大多数受体都是蛋白质且多为糖蛋白，"],"a":"D","e":"本页要点：绝大多数受体都是蛋白质且多为糖蛋白，"},"cards":null},{"i":12,"sec":"二、受体(receptor)","title":"亲水性","notes":"疏水/亲脂性\n神经递质、\n类固醇激素(甾类激     生长因子；\n素)；           多肽类激素\n视黄酸(类维生素A)\n甲状腺素","page":13,"level":"掌握","img":"assets/img/ch10/p013.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_mcq_4","mod":"二、受体(receptor)","modI":4,"q":"下列关于信号分子的描述中，不正确的是（                ）。","o":["A．神经递质属于亲脂性信号","B．本身不具有酶的活性","C．能传递信息","D．可作为作用底物"],"a":"A","e":"神经递质属于亲水性信号分子。","kp":"ch10_s4_11"}],"judge":[{"id":"ch10_judge_2","modI":4,"q":"所有的受体都是跨膜蛋白质。（       ）","a":"错","e":"细胞表面的受体多为跨膜糖蛋白，但细胞内的受体如基因调控蛋白等不一定是。","kp":"ch10_s4_11"}],"fill":[{"id":"ch10_fill_5","modI":4,"q":"根据信号转导机制和受体蛋白类型的不同，细胞表面受体可以分为______、______ 、 ______。","a":"离子通道耦联受体；G 蛋白耦联受体；酶连受体","kp":"ch10_s4_11"},{"id":"ch10_fill_7","modI":4,"q":"甾类激素诱导的基因活化分为两个阶段：______和______。","a":"直接活化少数特殊基因转录的初级反应阶段；初级反应的基因产物再活化其他基因产生延迟 的次级反应","kp":"ch10_s4_12"}],"short":[{"id":"ch10_short_5","modI":4,"q":"霍乱毒素通过什么机制引起腹泻的？","a":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","kp":"ch10_s4_11"},{"id":"ch10_short_14","modI":4,"q":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","a":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","kp":"ch10_s4_11"}],"calc":[{"id":"ch10_calc_5","modI":4,"q":"图解细胞表面受体调节基因表达的信号通路。","a":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","kp":"ch10_s4_11"}],"term":[]},{"i":5,"name":"三、NO信号[Ca2+→NO→cGMP→PKG]","slides":[{"i":13,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"三、NO信号[Ca2+→NO→cGMP→PKG]","notes":"(细胞内受体-鸟苷酸环化酶)\nNO作为信号分子的研究备受关注，R. Furchgott 等三位美国科\n学家因此获得1998年诺贝尔医学和生理学奖。\nNO是一种自由基性质的气体，具脂溶性，可快速扩散透过细胞\n膜，到达邻近靶细胞（细胞内受体结合）发挥作用。\n血管内皮细胞和神经细胞是NO的生成细胞。\n5-10 seconds), in the extracellular space在氧气和水的条件\n下被氧化为硝酸根或亚硝酸根。\n少心脏的工作负荷，降低心肌对氧气的需求。","page":14,"level":"掌握","img":"assets/img/ch10/p014.jpg","anim":null,"fig":null,"points":["NO acts only locally because it has a short half-life (about","硝酸甘油治疗心绞痛(心肌缺血)，即NO松弛了血管，减"],"check":{"q":"关于「NO信号[Ca2+→NO→cGMP→PKG]」，下列说法正确的是（　）","o":["A. 短期效应 靶蛋白。7次跨膜","B. NO acts only locally because it has a short half-life (about","C. NO在神经细胞中产生，参与大脑的学习记忆的生理","D. The receptor activation stimulated by light causes a fall rather than …"],"a":"B","e":"本页要点：NO acts only locally because it has a short half-life (about"},"cards":null},{"i":14,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"1998年诺贝尔生理学和医学奖","notes":"Robert F Furchgott, Louis J Ignarro和Ferid Murad，他们发现\n了“一氧化氮在心血管系统中作为信号分子\".\nLouis J Ignarro,         Ferid Murad, born 1936\nRobert F Furchgott,\nborn 1941                Dept. of Integrative\nborn 1916\nDept. of Pharmacology,   Dept. of Molecular and   Biology\nSUNY Health Science      Medical Pharmacology     Pharmacology and\nCenter                   UCLA School of           Physiology\nNew York                 Medicine                 University of Texas\nLos Angeles\nMedical School, Houston\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页介绍1998年诺贝尔生理学或医学奖。获奖者Robert F. Furchgott、Louis J. Ignarro和Ferid Murad发现“一氧化氮（nitric oxide, NO）在心血管系统中作为信号分子”。NO是气体信号分子，可松弛血管平滑肌、调节血压。该发现说明气体信号分子可穿膜直接发挥作用。考点：NO是气体信号分子的经典实例。","page":15,"level":"掌握","img":"assets/img/ch10/p015.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":15,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"Furchgott的“三明治”试验","notes":"内皮细胞层被去除了。\n胞舒张，扩张血管壁。 。\n(Ach-induced relaxation of blood vessels was dependent on the\nendothelium.)\n平滑肌细胞\n\n【读图讲解】\n本页介绍Furchgott的「三明治」试验。文字说明实验用两种主动脉：一种内皮细胞层完整，另一种去除内皮。结果乙酰胆碱只有在内皮细胞完整时才能使血管平滑肌细胞舒张、扩张血管壁，即ACh引起的血管舒张依赖完整内皮。图中左幅为去除内皮，ACh使平滑肌进一步收缩(曲线上升)；右幅为保留内皮，ACh使平滑肌舒张(曲线下降)，并据此发现来自内皮的舒张因子EDRF。要点：该实验证明血管舒张由内皮释放的扩散性因子介导。","page":16,"level":"掌握","img":"assets/img/ch10/p016.jpg","anim":null,"fig":null,"points":["两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","乙酰胆碱只有在內皮细胞完整时才会使血管平滑肌细"],"check":{"q":"关于「Furchgott的“三明治”试验」，下列说法正确的是（　）","o":["A. 异三聚体G蛋白：α, β, γ三亚基组成","B. 乙酰胆碱只有在內皮细胞完整时才会扩张血","C. 短期效应 靶蛋白。7次跨膜","D. 两种类型的主动脉：一种具有完整的内皮细胞层；另一种的"],"a":"D","e":"本页要点：两种类型的主动脉：一种具有完整的内皮细胞层；另一种的"},"cards":null},{"i":16,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"1980年Furchgott实验成功地呈现：","notes":"管壁，是一种未知的信息传导物质而造成血管平\n滑肌放松。\n→他命名这种信息传导物质为EDRF\n(endothelium-derived relaxing factor，內皮细胞舒\n张因子)。","page":17,"level":"掌握","img":"assets/img/ch10/p017.jpg","anim":null,"fig":null,"points":["乙酰胆碱只有在內皮细胞完整时才会扩张血"],"check":{"q":"关于「年Furchgott实验成功地呈现：」，下列说法正确的是（　）","o":["A. 乙酰胆碱只有在內皮细胞完整时才会扩张血","B. 同一种化学信号在不同细胞中","C. The binding site of the receptor has a complex structure","D. He reported that EDRF relaxed blood vessels."],"a":"A","e":"本页要点：乙酰胆碱只有在內皮细胞完整时才会扩张血"},"cards":null},{"i":17,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"⎯identified EDRF as a molecule by using spectral(光谱) analysis","notes":"Ignarro’s spectral analysis\nof hemoglobin.\nHemoglobin (yellow) exposed to\nendothelial cells that were\nstimulated to produce EDRF (green)\nHemoglobin (yellow) directly exposed\nto NO (green).\nThe shift of absorption curves is\nidentical, hence EDRF is NO.\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页讲述Ignarro的光谱分析（spectral analysis）实验。他报告内皮依赖性舒张因子（EDRF）能松弛血管，并利用血红蛋白（hemoglobin）光谱鉴定其本质：将内皮细胞受刺激产生的EDRF作用于血红蛋白，与NO直接作用者相比，吸收曲线位移完全相同，从而证明EDRF就是NO。考点：EDRF的化学本质为一氧化氮，实验中的对照与光谱比对是关键。","page":18,"level":"掌握","img":"assets/img/ch10/p018.jpg","anim":null,"fig":null,"points":["He reported that EDRF relaxed blood vessels."],"check":{"q":"关于「⎯identified EDRF as a mo…」，下列说法正确的是（　）","o":["A. G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","B. He reported that EDRF relaxed blood vessels.","C. 绝大多数受体都是蛋白质且多为糖蛋白，","D. 异三聚体G蛋白：α, β, γ三亚基组成"],"a":"B","e":"本页要点：He reported that EDRF relaxed blood vessels."},"cards":null},{"i":18,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"鸟苷酸环化酶","notes":"Murad’s enzyme activation\nNO 通过刺激鸟苷酸环化酶(Guanylyl cyclase)诱导\ncGMP的合成，抑制myosin-actin的相互作用，导致血\n管平滑肌舒张。\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页讲解】\n本页讲解NO信号通路中的鸟苷酸环化酶（Guanylyl cyclase），以Murad的酶激活实验为背景。NO通过刺激鸟苷酸环化酶，诱导cGMP（环鸟苷酸）的合成；cGMP进而抑制肌球蛋白与肌动蛋白（myosin-actin）的相互作用，导致血管平滑肌舒张。这也解释了硝酸甘油等药物舒张血管的分子机制。考点联系翟中和《细胞生物学》第九章细胞信号转导第三节G蛋白偶联受体及相关通路，需掌握“Ca2+→NO→cGMP→PKG”及NO作为气体信号分子的作用特点。","page":19,"level":"掌握","img":"assets/img/ch10/p019.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":19,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"血管神经末梢释放乙酰胆碱(acetylcholine, ACh)","notes":"血管内皮细胞膜上：乙酰胆碱受体GPCR\n→磷脂酶C激活，产生IP3\nCa2+ 通道开放(Ca2+升高)\n→ Niric oxide synthase, NOS\nL-精氨酸→ NO+ L瓜氨酸\n● NO\n鸟苷酸环化酶(平滑肌细胞内受体)\nGTP→cGMP合成增多\n●活化PKG，抑制actin/myosin\n血管平滑肌细胞舒张，血管扩张变大、血流通畅","page":20,"level":"掌握","img":"assets/img/ch10/p020.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":20,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"NO使血管平滑肌舒张：","notes":"硝酸甘油治疗心绞痛-心肌缺血；NO松弛血管)\n\n【读图讲解】\n本页说明NO使血管平滑肌舒张的机制，并联系硝酸甘油治疗心绞痛。图中标注5个步骤：①乙酰胆碱(ACh)与血管内皮细胞表面受体结合；②Ca2+进入内皮细胞；③在Ca2+和NO合酶作用下，精氨酸(Arg)转化为NO；④NO扩散进入邻近平滑肌细胞；⑤NO激活鸟苷酸环化酶，使GTP生成cGMP，cGMP引起平滑肌松弛、血管扩张。要点：NO是气体性信号分子，通过cGMP途径舒张血管，故硝酸甘油可缓解心肌缺血。","page":21,"level":"掌握","img":"assets/img/ch10/p021.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":21,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"NO在神经系统疾病中的双重作用","notes":"功能。\n暂的通过NOS的激活而导致的NO增高，进而使脑血\n管扩张、增加脑血流、抗血小板凝集，从而抗缺血性\n脑损伤而起保护作用。\n吞噬细胞会诱导产生大量NOS，由此造成的NO过度\n释放则引起神经毒作用。","page":22,"level":"掌握","img":"assets/img/ch10/p022.jpg","anim":null,"fig":null,"points":["NO在神经细胞中产生，参与大脑的学习记忆的生理","如脑缺血损伤，研究表明一旦脑缺血发生后即有短","但如果病程发展到中、晚期，梗死灶内炎症细胞、"],"check":{"q":"关于「NO在神经系统疾病中的双重作用」，下列说法正确的是（　）","o":["A. 两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","B. NO在神经细胞中产生，参与大脑的学习记忆的生理","C. 既有信号结合位点，本身又是离子通道的一部分","D. NO acts only locally because it has a short half-life (about"],"a":"B","e":"本页要点：NO在神经细胞中产生，参与大脑的学习记忆的生理"},"cards":null}],"mcq":[{"id":"ch10_amcq_1","mod":"三、NO信号[Ca2+→NO→cGMP→PKG]","modI":5,"q":"关于「NO信号[Ca2+→NO→cGMP→PKG]」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. NO acts only locally because it has a short half-life (about","C. 同一个细胞上不同受体应答不","D. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基"],"a":"B","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13"}],"judge":[{"id":"ch10_judge_6","modI":5,"q":"来源于质膜的不同信号能通过细胞内不同信号途径间的相互作用而被整合。（         ）","a":"对","e":"","kp":"ch10_s5_18"},{"id":"ch10_ajudge_2","modI":5,"q":"NO acts only locally because it has a short half-life (about","a":"对","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":6,"name":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","slides":[{"i":22,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","notes":"多肽或水溶性分子)\n离子通道偶联受体\n跨膜结构域和胞内酶活性结构域","page":23,"level":"掌握","img":"assets/img/ch10/p023.jpg","anim":null,"fig":null,"points":["既有信号结合位点，本身又是离子通道的一部分","跨膜信号转导无需中间步骤，反应快","常见于可兴奋细胞间的突触信号传递如：nAchR","G蛋白偶联型受体","必须与G蛋白偶联才能产生胞内信使，传递信号","G蛋白为αβγ三个亚基组成的异三聚体G蛋白","进化相当保守，酵母→人","酶联受体","本身既是受体又是酶，有3个结构区:胞外配体结合域，","常见生长因子受体，具有酪氨酸蛋白激酶活性"],"check":{"q":"关于「细胞膜表面的受体(信号分子为亲水蛋白质、」，下列说法正确的是（　）","o":["A. 异三聚体G蛋白：α, β, γ三亚基组成","B. 乙酰胆碱只有在內皮细胞完整时才会扩张血","C. 既有信号结合位点，本身又是离子通道的一部分","D. 短期效应 靶蛋白。7次跨膜"],"a":"C","e":"本页要点：既有信号结合位点，本身又是离子通道的一部分"},"cards":null},{"i":23,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"G-蛋白偶联受体与信","notes":"号分子结合时，信号\n先传递到一个G-蛋白\n(GTP结合蛋白)，然\n酶类和蛋白活性调节     后再通过它激活其它\n酶联受体本身在细\n胞内侧一端具有酶的\n活性，当其胞外端与\n配体信号分子结合后，\n单次跨膜   二聚体化：激活的普遍机制   则启动细胞膜内侧另\n一端的酶活性。只\n基因表达调控    跨膜1次","page":24,"level":"掌握","img":"assets/img/ch10/p024.jpg","anim":null,"fig":null,"points":["短期效应         靶蛋白。7次跨膜","长期效应"],"check":{"q":"关于「G-蛋白偶联受体与信」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. The binding site of the receptor has a complex structure","C. He reported that EDRF relaxed blood vessels.","D. 短期效应 靶蛋白。7次跨膜"],"a":"D","e":"本页要点：短期效应 靶蛋白。7次跨膜"},"cards":null},{"i":24,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"2021诺贝尔生理和医学奖","notes":"温度和机械压力如何\n被感知，转化为神经\n冲动信号？\nHow are nerve\nimpluses initiated so\nthat temperature and\npressure can be\nperceived?\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n•  recognition）●概念：细胞通过其表面的受体与胞外信号物质分子（配体）选择性地相互作用，进而导致胞内一系列生理生化变化，最终表现为细胞整体的生物学效应的过程。●信号通路（signaling pathway）细胞识别是通过各种不同的信号通路实现的。细胞接受外界信号，通过一整套特定的机制，将胞外信号转导为胞内信号，最终调节特定基因的表达，引起细胞的应答反应，这种反应系列称之为细胞信号通路。\n\n【本页英文讲解】\n本页主题为2021年诺贝尔生理学或医学奖。核心问题：温度和机械压力如何被感知并转化为神经冲动信号？即神经冲动（nerve impulses）如何被引发，使机体感知温度与压力。该奖授予David Julius与Ardem Patapoutian，分别发现温度感受器和机械感受器。考点：感受器属于离子通道，外界物理刺激可直接门控通道，把物理信号转换为电信号。","page":25,"level":"掌握","img":"assets/img/ch10/p025.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":25,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"戴维·朱利叶斯利用辣椒素（一种来自辣椒的刺激性化合物，可引起灼","notes":"烧感）来识别皮肤神经末梢中对热有反应的感受器。\nTRPV1，encoded a novel ion channel protein, is a heat-sensing\nreceptor 热敏受体（capsaicin receptor) and is activated at temperatures\nperceived as painful. 该受体能在令人感到疼痛的温度下被激活。\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":26,"level":"掌握","img":"assets/img/ch10/p026.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":26,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"阿尔代姆·帕塔普蒂","notes":"安利用压敏细胞发现\n了一种可对皮肤和内\n脏中的机械刺激做出\n反应的新型感受器。\nCultured\nmechanosensitive\ncells were poked\nwith a micropipette.\nPiezo1 and Piezo2 are ion channels that are directly activated\nby the exertion of pressure on cell membrane.\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n•  recognition）●概念：细胞通过其表面的受体与胞外信号物质分子（配体）选择性地相互作用，进而导致胞内一系列生理生化变化，最终表现为细胞整体的生物学效应的过程。●信号通路（signaling pathway）细胞识别是通过各种不同的信号通路实现的。细胞接受外界信号，通过一整套特定的机制，将胞外信号转导为胞内信号，最终调节特定基因的表达，引起细胞的应答反应，这种反应系列称之为细胞信号通路。\n\n【本页英文讲解】\n本页介绍阿尔代姆·帕塔普蒂安（Ardem Patapoutian）。研究者用微吸管（micropipette）戳压压敏细胞（mechanosensitive cells），发现一种可对皮肤和内脏机械刺激作出反应的新型感受器。Piezo1和Piezo2是离子通道，可被细胞膜上的压力直接激活。考点：Piezo是机械门控离子通道，可把机械力转为电信号。","page":27,"level":"掌握","img":"assets/img/ch10/p027.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_mcq_6","mod":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","modI":6,"q":"表皮生长因子（EGF）的穿膜信号转导是通过（                ）实现的。","o":["A．活化酪氨酸激酶","B．活化酪氨酸磷酸酶","C．cAMP 调节途径","D．cGMP 调节途径"],"a":"A","e":"EGF 的受体分子是酪氨酸激酶受体，EGF 可以活化酪氨酸激酶受体，使其获得激 酶活性，从而传导信号。","kp":"ch10_s6_22"}],"judge":[{"id":"ch10_judge_4","modI":6,"q":"激素受体都具有酪氨酸受体结构域。(       )","a":"错","e":"激素受体都具有各自激素的特异结构域。","kp":"ch10_s6_22"}],"fill":[{"id":"ch10_fill_3","modI":6,"q":"从蛋白结构看，蛋白激酶 A 是由______组成的，而蛋白激酶 C 是______组成。","a":"四个亚基；只有一条肽链","kp":"ch10_s6_22"},{"id":"ch10_fill_10","modI":6,"q":"受体自磷酸化的结果是激活了受体的______活性，磷酸化的酪氨酸残基可被含有______ 结构域的胞内信号蛋白识别。","a":"酪氨酸蛋白激酶；SH2","kp":"ch10_s6_22"},{"id":"ch10_fill_15","modI":6,"q":"细胞内的受体具有同源性，一般由 800 个氨基酸组成，分为三个结构域，即______，______ 和______。","a":"C 端与信号分子结合部位；中部与 DNA 结合部位；N 端激活基因转录部位查看答 案","kp":"ch10_s6_22"}],"short":[],"calc":[{"id":"ch10_calc_1","modI":6,"q":"试述细胞接受化学信号后调节基因表达的途径？","a":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","kp":"ch10_s6_23"}],"term":[{"id":"ch10_term_5","modI":6,"term":"离子通道耦联受体（ion-channel-coupled receptor）。","def":"离子通道耦联受体是由多亚基组成的受体一离子通道复合体，本身既有结合位点，又是 离子通道，其跨膜信号转导无需中间步骤。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_8","modI":6,"term":"RTK","def":"RTK 的中文名称是受体酪氨酸激酶。受体酪氨酸激酶是一类酶联受体，既是受体，又 具有酶功能。当 RTK 与其配体结合后，两个受体在膜上二聚化，两个受体分子具有微弱的 蛋白激酶活性，当它们相互靠近后通过相互磷酸化的机制将二者自身的蛋白激酶活化，使下 游蛋白的酪氨酸残基磷酸化，从而实现信号转导的功能。所有的受体酪氨酸激酶都由三个部 分组成：具配体结合位点的胞外结构域、单次跨膜的疏水α螺旋区、具酪氨酸蛋白激酶活性 的胞内结构域。","kps":"","kp":"ch10_s6_22"}]},{"i":7,"name":"4.1 G protein-Cou","slides":[{"i":27,"sec":"4.1    G protein-Cou","title":"G蛋白偶联的受体","notes":"4.1    G protein-Coupled receptors (GPCR)\n细胞表面受体的最大家族，哺乳动物\n细胞中已鉴定有数百个之多，可结合\n蛋白或肽类激素、神经递质、氨基酸\n或脂肪酸衍生物等多种信号分子。\n但已有的分析表明，所有G蛋白偶联受体都\n有类似结构：一条来回跨膜7次的多肽\n链组成。\n如脊椎动物眼中的光激活受体－视紫\n红质和鼻中的嗅觉受体、味觉受体。\nLigand(orange)\nThere are more than 800 GPCRs in humans, and      binds in a pocket\nin mice there are about 1000 concerned with the   between the helices\nsense of smell alone.\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系","page":28,"level":"掌握","img":"assets/img/ch10/p028.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":28,"sec":"4.1    G protein-Cou","title":"视紫红质","notes":"视网膜杆细胞中视紫                                     －G-蛋白偶联受体\n红质的三维结构\n当rhodopsin蛋白中\n的光吸收基团(red)吸\n收光量子后，视紫红\n视网膜的视杆细胞对光线                                          质被激活，其蛋白构\n非常敏感，负责接收弱光                                          象发生改变，进而将\n刺激。                                                  信号传递给细胞内的\nG-蛋白。\n人类视杆细胞含有大约\n4×107个rhodopsin。\nthe level of cGMP.\n(光信号下G蛋白偶联受体-视紫红质激活，引起cGMP水平下降,视\n杆细胞膜上阳离子通道关闭，膜超极化。","page":29,"level":"掌握","img":"assets/img/ch10/p029.jpg","anim":null,"fig":null,"points":["The receptor activation stimulated by light causes a fall rather than a rise in"],"check":{"q":"关于「视紫红质」，下列说法正确的是（　）","o":["A. The receptor activation stimulated by light causes a fall rather than …","B. 两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","C. 既有信号结合位点，本身又是离子通道的一部分","D. NO acts only locally because it has a short half-life (about"],"a":"A","e":"本页要点：The receptor activation stimulated by light causes a fall rather than …"},"cards":null},{"i":29,"sec":"4.1    G protein-Cou","title":"视杆细胞膜上","notes":"GPCR：光受体\n① 弱光下，GPCR视紫红质激活\n② cGMP磷酸二酯酶PDE催化cGMP→GMP，胞质内\ncGMP水平降低。\n③ 阳离子通道关闭(Na+, Ca2+)\n④ 细胞膜超极化","page":30,"level":"掌握","img":"assets/img/ch10/p030.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":30,"sec":"4.1    G protein-Cou","title":"The Nobel Prize in Chemistry 2012","notes":"\"for studies of G-protein-coupled receptors\"\nRobert J. Lefkowitz    Brian K. Kobilka\nRobert J. Lefkowitz,        Brian K. Kobilka,\nU.S. citizen.               U.S. citizen.\nStanford University School\nDuke University Medical\nof Medicine\nCenter\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页主题为2012年诺贝尔化学奖，获奖理由是“对G蛋白偶联受体的研究”，获奖者为Robert J. Lefkowitz和Brian K. Kobilka。G蛋白偶联受体（G-protein-coupled receptors, GPCR）是最大的膜受体家族，通过激活异源三聚体G蛋白传递信号。考点：GPCR七次跨膜的结构特征及其作为药物靶点的地位。","page":31,"level":"掌握","img":"assets/img/ch10/p031.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":31,"sec":"4.1    G protein-Cou","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• BRAIN/EYES/HEART/LUNGS/MUSCLE/LIVER/FAT CELLS/STOMACH&INTESTINES —— 脑/眼/心/肺/肌肉/肝/脂肪细胞/胃肠（应激时的反应器官）\n• adrenal gland / medulla / cortex —— 肾上腺 / 髓质 / 皮质\n• adrenalin, noradrenalin, cortisol —— 肾上腺素、去甲肾上腺素、皮质醇\n• Figure 1. Time to flee! —— 图1 应激逃逸：脑发出神经信号与激素激活肾上腺，应激激素入血，全身细胞通过受体感知\n【读图讲解】\n情景图：应激时脑发信号并经激素激活肾上腺(adrenal gland)，引起瞳孔放大、心率加快、支气管扩张、肌肉血流增加、肝释放糖、消化道血流减少。考点：神经-体液调节；肾上腺髓质分泌肾上腺素/去甲肾上腺素、皮质分泌皮质醇，靶细胞靠受体感知信号。","page":32,"level":"掌握","img":"assets/img/ch10/p032.jpg","anim":null,"fig":null,"points":["BRAIN","EYES","HEART","Nervesignalswarntherest","Thepupils","Adrenalinandnoradrenalin","of thebody.Thebrainalso","expand.The"],"check":null,"cards":null},{"i":32,"sec":"4.1    G protein-Cou","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• 1 A hormone binds to the receptor —— 1 激素与受体结合\n• 2 receptor alters shape; G-protein binds & is activated —— 2 受体变构，G蛋白结合并被激活\n• 3 activated G-protein breaks apart; free α-subunit triggers reactions —— 3 活化G蛋白解离，游离α亚基触发反应链改变细胞代谢\n• 4 a new G-protein binds; receptor activates hundreds before hormone detaches —— 4 新G蛋白结合；激素脱离前受体可激活上百个G蛋白\n• hormone/receptor/cell membrane/α,β,γ —— 激素 / 受体 / 细胞膜 / α、β、γ 亚基\n• Figure 2 —— 图2 激素/气味/味觉分子结合表面受体→胞内级联反应\n【读图讲解】\n四步过程图：激素(hormone)结合膜受体(receptor)→受体变构激活G蛋白并使其解离→游离α亚基触发胞内反应链；一个激素可反复激活上百个G蛋白。考点：G蛋白偶联受体信号转导与信号放大(α/β/γ亚基)。","page":33,"level":"掌握","img":"assets/img/ch10/p033.jpg","anim":null,"fig":null,"points":["Thereceptoraltersshape.","Ahormonebinds","Inside thecell,theG-protein","to thereceptor.","bindsand isactivated.","hormone","receptor","33377737333"],"check":null,"cards":null},{"i":33,"sec":"4.1    G protein-Cou","title":"Structural model of G","notes":"protein-coupled\nreceptor (rhodopsin)\nand its associated\nheterotrimeric G\nprotein (2001, 2006)\nThe 3 subunits of the G\nprotein are color coded.\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页展示G蛋白偶联受体（GPCR，此处为视紫红质rhodopsin）及其偶联的异源三聚体G蛋白（heterotrimeric G protein）的结构模型，成果发表于2001、2006年。图中G蛋白的3个亚基（α、β、γ）用不同颜色标出。核心概念：受体与G蛋白偶联是信号跨膜传递的关键一步。考点：G蛋白由α、β、γ三亚基构成，α亚基结合并水解GTP。","page":34,"level":"掌握","img":"assets/img/ch10/p034.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_amcq_3","mod":"4.1 G protein-Cou","modI":7,"q":"关于「G protein-Cou」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. 同一个细胞上不同受体应答不","C. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","D. The receptor activation stimulated by light causes a fall rather than a rise in"],"a":"D","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27"}],"judge":[{"id":"ch10_ajudge_4","modI":7,"q":"The receptor activation stimulated by light causes a fall rather than a rise in","a":"对","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27"}],"fill":[],"short":[],"calc":[{"id":"ch10_calc_2","modI":7,"q":"从受体的角度解读家族性高胆固醇血症的发病机理。","a":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","kp":"ch10_s7_27"}],"term":[]},{"i":8,"name":"4.1.1 G蛋白与跨膜信号转导","slides":[{"i":34,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"4.1.1   G蛋白与跨膜信号转导","notes":"蛋白两大类。具有GTPase的作用，通过对结合的GTP\n的可逆水解来完成静止态与激活态的转换。为细胞内\n信号转导过程中重要的分子开关。\n三个亚基组成， α亚基具内在的GTP水解酶活性。 α\n－GDP为静止态， α－GTP激活态。","page":35,"level":"掌握","img":"assets/img/ch10/p035.jpg","anim":null,"fig":null,"points":["G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","G蛋白偶联受体中的是异三聚体G蛋白，由α、β、γ"],"check":{"q":"关于「G蛋白与跨膜信号转导」，下列说法正确的是（　）","o":["A. NO在神经细胞中产生，参与大脑的学习记忆的生理","B. The receptor activation stimulated by light causes a fall rather than …","C. G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","D. 离子通道(K+, Na+等)"],"a":"C","e":"本页要点：G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G"},"cards":null},{"i":35,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"异三聚体G-蛋白","notes":"◆组成:  一般由三个亚基组成, 分别叫α、 β、γ,\n其中β、γ两亚基通常紧密结合在一起, 只有在蛋白\n变性时才分开。\n◆功能位点: α-亚基具有三个功能位点：\n①GTP结合位点;\n②鸟苷三磷酸水解酶(GTPase)活性;\n③ADP-核糖化位点。","page":36,"level":"掌握","img":"assets/img/ch10/p036.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":36,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"无活性状态","notes":"α亚基结合GTP，激活并与β,γ亚基分开，与特\n定靶蛋白结合。\nG蛋白的激活态\n\n【读图讲解】\n本页展示G蛋白的激活态。上方为无活性状态：G蛋白由α、β、γ三亚基组成并结合GDP，静息时与受体相邻(左)或分离(右)。当信号分子与受体结合后，受体使α亚基上的GDP被GTP置换，α亚基结合GTP而被激活，并与βγ亚基分开，分别去结合特定靶蛋白。下方标注activated α subunit(GTP)与activated βγ complex，即G蛋白的激活态。要点：G蛋白以GDP/GTP结合状态充当分子开关，GTP结合型为「开」，并解离成α与βγ两部分发挥作用。","page":37,"level":"掌握","img":"assets/img/ch10/p037.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":37,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"心肌细胞","notes":"G-偶联受体和神经\n递质乙酰胆碱结合\nG蛋白-GTP激活\n激活的βγ亚基\n打开心肌细胞质膜\n上的K+通道\nK+到胞外，降低细\n胞的兴奋性。\nα亚基内在的GTPase活性将GTP水解\n为GDP，使其与靶蛋白脱离，并与βγ   G蛋白灭活态（静止态）\n复合物重新形成G蛋白－GDP的静止态","page":38,"level":"掌握","img":"assets/img/ch10/p038.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":38,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"α亚基内在的","notes":"GTPase活性将GTP\n水解为GDP，使其与\n靶蛋白脱离，并与βγ复\n合物重新形成G蛋白－     G蛋白灭活态\nGDP的静止态","page":39,"level":"掌握","img":"assets/img/ch10/p039.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":39,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"小G蛋白","notes":"白，分子量只有20－30kDa。Ras , Rho,\nRab等\n●具有两种鸟嘌呤核苷酸的结合形式即结合GTP\n有活性，结合GDP无活性。\n●也具有内源GTPase活性，由它完成GTP,GDP的\n转换，结束一次信号传导过程。\n【结合课本/笔记】cAMP信号通路●反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录●组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶●GPLR的失敏（desensitization）与减量调节●细菌毒素对G蛋白的修饰作用","page":40,"level":"掌握","img":"assets/img/ch10/p040.jpg","anim":null,"fig":null,"points":["异三聚体G蛋白：α, β, γ三亚基组成","小G蛋白：只有一条多肽链构成的单体G蛋","相同点："],"check":{"q":"关于「小G蛋白」，下列说法正确的是（　）","o":["A. 离子通道(K+, Na+等)","B. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","C. 同一种化学信号在不同细胞中","D. 异三聚体G蛋白：α, β, γ三亚基组成"],"a":"D","e":"本页要点：异三聚体G蛋白：α, β, γ三亚基组成"},"cards":null},{"i":40,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Table 15-5 Ras superfamily of monomeric GTPases —— 表15-5 单体GTP酶的Ras超家族\n• Ras (H/K/N-Ras): relay signals from RTKs —— Ras(H/K/N-Ras)：传递RTK信号\n• Rheb: activates mTOR to stimulate growth —— Rheb：激活mTOR促生长\n• Rap1: activated by cAMP-GEF; influences adhesion via integrins —— Rap1：由cAMP-GEF激活，经整合素影响黏附\n• Rho/Rac/Cdc42: relay signals to cytoskeleton —— Rho/Rac/Cdc42：向细胞骨架传递信号\n• ARF1-6: coats on vesicles —— ARF1-6：囊泡外被组装\n• Rab1-60: vesicle traffic —— Rab1-60：囊泡运输\n• Ran: spindle assembly & nuclear transport —— Ran：纺锤体组装与核运输\n【读图讲解】\n表格(Table 15-5)：Ras 超家族单体GTP酶——Ras(H/K/N-Ras，转导RTK信号)、Rheb、Rap1，以及Rho(调控细胞骨架)、ARF(囊泡衣被)、Rab(囊泡运输)、Ran(核转运与纺锤体)。考点：各成员功能；Ras 突变与癌症。","page":41,"level":"掌握","img":"assets/img/ch10/p041.jpg","anim":null,"fig":null,"points":["Family","Somefamily","Somefunctions","members","Ras","H-Ras, K-Ras,","RelaysignalsfromRTKs","N-Ras"],"check":null,"cards":null},{"i":41,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"GTPase 分子开关的调节蛋白","notes":"GTPase 超家族：\n三聚体G蛋白\n单体小 G蛋白\n\n【读图讲解】\n本页讲GTPase分子开关的调节蛋白。GTPase超家族包括三聚体G蛋白和单体小G蛋白。图中循环示意：失活态单体GTPase结合GDP(OFF)；GEF催化GDP换成GTP，使其变为结合GTP的活性态(ON)；而GAP能促进其GTP酶活性，使GTP水解为GDP并释放Pi，从而回到失活态。要点：G蛋白的开与关取决于所结合的是GTP还是GDP，GEF促进活化、GAP促进失活，二者共同调控开关循环，这是信号转导的通用机制。","page":42,"level":"掌握","img":"assets/img/ch10/p042.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":42,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"●GTPase激活蛋白(GTPase activating proteins, GAP):","notes":"加速GTP的水解，缩短应答时间。⎯In an “off” state\n●鸟苷交换因子（guanine nucleotide-exchange factor,\nGEF)：促进GDP从G蛋白上解离，结合GTP (细胞中\nGTP浓度is 10 times greater than GDP)，激活G蛋白。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页讲G蛋白循环的调控。GTPase激活蛋白（GTPase activating protein, GAP）加速GTP水解，使G蛋白关闭，缩短应答时间；鸟苷交换因子（guanine nucleotide-exchange factor, GEF）促进GDP解离并结合GTP而激活，因胞内GTP约为GDP的10倍。考点：GAP关闭、GEF激活，控制信号时程。","page":43,"level":"掌握","img":"assets/img/ch10/p043.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":43,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"一种肠道内繁殖的细菌在","notes":"肠道产生霍乱毒素，进\n入小肠上皮细胞内\n霍乱毒素具有催化作用\n→ G蛋白核糖化\n抑制α亚基GTPase活性，抑制了GTP的水解\nGTP永久结合在α亚基上，G蛋白处于持续活化状态\n腺苷酸环化酶永久活化，致使小肠上皮细胞的胞质中\ncAMP合成失控，增加100倍以上。\n引起大量的Na+和水外流到肠腔，产生严重腹泻而脱水。","page":44,"level":"掌握","img":"assets/img/ch10/p044.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":44,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"The mechanisms that shut off a","notes":"signal are as important as the\nmechanisms that turn it on.\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 离子通道偶联的受体介导的信号跨膜传递●信号途径●特点：●受体/离子通道复合体，四次/六次跨膜蛋白●跨膜信号转导无需中间步骤●主要存在于神经细胞或其他可兴奋细胞间的突触信号传递●有选择性：配体的特异性选择和运输离子的选择性\n\n【本页英文讲解】\n本页强调一个基本原则：关闭信号的机制与开启信号的机制同等重要。若信号不能及时终止，会导致应答持续、紊乱甚至癌变。原文仅给出这一命题，未展开具体途径。结合翟中和教材第九章，常见的关闭机制包括：配体降解、受体脱敏与内化、GAP加速GTP水解、第二信使被磷酸二酯酶降解等。考点：信号终止与信号启动同等关键。","page":45,"level":"掌握","img":"assets/img/ch10/p045.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":45,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"1994年诺贝尔生理学和医学奖","notes":"\"for their discovery of G-proteins and the role of these\nproteins in signal transduction in cells\nAlfred G. Gilman\nMartin Rodbell\nUniversity of Texas      National Institute of\nSouthwestern Medical     Environmental Health Sciences\nCenter at Dallas         Research Triangle Park, NC,\nDallas, TX, USA          USA\nborn 1941                Born 1925, died 1998\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页介绍1994年诺贝尔生理学或医学奖，获奖理由是“发现G蛋白及其在细胞信号转导中的作用”。获奖者为Alfred G. Gilman（得克萨斯大学西南医学中心）和Martin Rodbell（美国国家环境卫生科学研究所）。他们揭示了G蛋白作为信号转导中转分子的功能，为GPCR通路奠定基础。考点：G蛋白的发现是细胞信号转导研究的里程碑。","page":46,"level":"掌握","img":"assets/img/ch10/p046.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":46,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-protein","notes":"activation and\ninactivation cycle\n...with GTP and the G\nproteins is activated. The\nsubunits separate.\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页主题为G蛋白（G-protein）的激活与失活循环。原文指出：当G蛋白与GTP结合时即被激活，其亚基随之分离。核心机制：受体激活后促使G蛋白α亚基释放GDP并结合GTP，α亚基与βγ亚基解离，激活的α亚基（或βγ）再去调节下游效应器；随后α亚基固有的GTPase水解GTP，使亚基重新结合、G蛋白失活。考点：G蛋白的分子开关循环。","page":47,"level":"掌握","img":"assets/img/ch10/p047.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":47,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-蛋白偶联反应具有特异性","notes":"G-蛋白的重要意义：在人类视网膜的圆柱细胞和圆锥细胞中\n发现有特定类型的G-蛋白。\n1. G proteins in our sense organs\ntranslate environmental information\ninto a language that the G proteins in\nthe brain can understand.\n2. G proteins in the nose are activated\nby olfactory stimuli.\n3. G proteins of the tongue register\ntaste.\n1.存在于我们的感受器官中的G-蛋白，能够将环境信息翻译\n成一种可以被大脑中的G-蛋白所理解的一种语言。\n2.鼻子中的G-蛋白在嗅觉的刺激作用下被激活。\n3. 舌头上的G-蛋白能够识别味道。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 磷脂酰肌醇信号通路● “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→","page":48,"level":"理解","img":"assets/img/ch10/p048.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":48,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-蛋白能够对 When in a rage, our adrenals release","notes":"激素产生反应 adrenaline into the blood. When it\nreaches the liver, glucose is formed,\ngiving energy for fight or flight. The\nheart and the blood vessels also become\nprepared.\n当人愤怒的时候，我们的肾上\n腺就会分泌肾上腺素到我们的\n血液中，当肾上腺素到达肝脏\n的时候，激素＋受体→G蛋白，\n信号通路→葡萄糖，为我们搏\n斗或逃跑提供能量。心脏和血\n管也同时进入了紧张状态。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 离子通道偶联的受体介导的信号跨膜传递●信号途径●特点：●受体/离子通道复合体，四次/六次跨膜蛋白●跨膜信号转导无需中间步骤●主要存在于神经细胞或其他可兴奋细胞间的突触信号传递●有选择性：配体的特异性选择和运输离子的选择性","page":49,"level":"掌握","img":"assets/img/ch10/p049.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":49,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"●   ●G蛋白偶联受体信号","notes":"通路的效应器\n\n【读图讲解】\n本页为G蛋白偶联受体(GPCR)信号通路的效应器示意。图中配体(Ligand)结合七次跨膜的受体(标①，有NH2端与COOH端)；受体激活G蛋白(标②，α、β、γ三亚基，结合GDP或GTP)；活化的G蛋白再去调节效应器(标③)。右侧文字列出效应器类型：离子通道(K+、Na+等)、腺苷酸环化酶(生成cAMP激活PKA)、磷脂酶C(生成IP3和DAG)。要点：效应器产生胞内第二信使，把胞外信号放大并转换为胞内反应。","page":50,"level":"掌握","img":"assets/img/ch10/p050.jpg","anim":null,"fig":null,"points":["离子通道(K+, Na+等)","腺苷酸环化酶→cAMP-PKA","磷脂酶C→IP3-DAG"],"check":{"q":"关于「● ●G蛋白偶联受体信号」，下列说法正确的是（　）","o":["A. 两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","B. 离子通道(K+, Na+等)","C. 既有信号结合位点，本身又是离子通道的一部分","D. NO acts only locally because it has a short half-life (about"],"a":"B","e":"本页要点：离子通道(K+, Na+等)"},"cards":null},{"i":50,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"心肌细胞：乙酰胆碱受体GPCR   效应器为","notes":"(一) 激活离子通道\nK+离子通道开放，\n细胞内K+外流\n膜超极化\n减缓心肌收缩频率。","page":51,"level":"掌握","img":"assets/img/ch10/p051.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch10_mcq_2","mod":"4.1.1   G蛋白与跨膜信号转导","modI":8,"q":"下列不具有分子开关作用的蛋白是（            ）。","o":["A．G 蛋白","B．Ras 蛋白","C．接头蛋白","D．Rho 蛋白"],"a":"C","e":"接头蛋白在信号通路中既不能被磷酸化，也不能结合 GTP，它只起偶联作用。而 G 蛋白、Ras 蛋白和 Rho 蛋白分别在不同的信号通路中发挥了分子开关的作用，当其结合 GTP 时处于活化状态，当其结合 GDP 时处于失活状态。Rho 在整联蛋白介导的信号传递中起分 子开关的作用。","kp":"ch10_s8_41"}],"judge":[{"id":"ch10_judge_3","modI":8,"q":"G 蛋白偶联受体被激活后，使相应的 G 蛋白解离成α、β、γ三个亚基，以进行信号传递。 （      ）","a":"错","e":"G 蛋白三聚体结合 GTP 后解离出成α亚基和βγ亚基复合物，β与γ亚基并未解离。","kp":"ch10_s8_49"},{"id":"ch10_judge_5","modI":8,"q":"G 蛋白耦联的受体的 N 端结合 G 蛋白，C 端结合胞外信号。( )","a":"错","e":"G 蛋白耦联的受体的 N 端在细胞外侧结合胞外信号，C 端在细胞胞质侧。","kp":"ch10_s8_36"},{"id":"ch10_judge_11","modI":8,"q":"细胞受体与腺苷酸环化酶同在质膜上，是相互分离的在功能上相关的两种蛋白。（                        ）","a":"对","e":"","kp":"ch10_s8_49"}],"fill":[{"id":"ch10_fill_2","modI":8,"q":"由 G 蛋白偶联受体所介导的细胞信号通路主要包括 ______、______和______。","a":"cAMP 信号通路；磷脂酰肌醇信号通路；G 蛋白偶联离子通道的信号通路","kp":"ch10_s8_49"},{"id":"ch10_fill_9","modI":8,"q":"G 蛋白的______结构可以变化，并可以结合______使其成为关闭态。","a":"α亚基；ADP","kp":"ch10_s8_36"},{"id":"ch10_fill_13","modI":8,"q":"Gs 的α亚基和 G 的α亚基上都有细胞毒素 ADP 核糖基化位点，但结合的毒素是不同的， 前者结合是______，后者结合的是______。","a":"百日咳毒素；霍乱毒素","kp":"ch10_s8_35"},{"id":"ch10_fill_16","modI":8,"q":"Ras 蛋白在 RTKs 介导的信号通路中起着关键作用，具有 活性，当结合______时为活 化状态，当结合 时为失活状态。GAP 增强 Ras 的 。","a":"GTPase；GTP；GDP；失活","kp":"ch10_s8_39"}],"short":[{"id":"ch10_short_2","modI":8,"q":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","a":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","kp":"ch10_s8_34"},{"id":"ch10_short_4","modI":8,"q":"由哪些蛋白调控单体 G 蛋白的活性？","a":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","kp":"ch10_s8_41"},{"id":"ch10_short_7","modI":8,"q":"简述 NO 的作用机制。","a":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","kp":"ch10_s8_34"},{"id":"ch10_short_8","modI":8,"q":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","a":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","kp":"ch10_s8_49"},{"id":"ch10_short_9","modI":8,"q":"比较植物中的信号传导途径和动物中的信号传导途径。","a":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","kp":"ch10_s8_39"},{"id":"ch10_short_10","modI":8,"q":"列表比较 PKA 与 PKC 信号转导系统。","a":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","kp":"ch10_s8_34"}],"calc":[{"id":"ch10_calc_3","modI":8,"q":"何谓信号转导中的分子开关机制？举例说明。","a":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","kp":"ch10_s8_34"},{"id":"ch10_calc_4","modI":8,"q":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","a":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","kp":"ch10_s8_49"}],"term":[{"id":"ch10_term_2","modI":8,"term":"G 蛋白（trimeric GTP-binding regulatory protein）。","def":"G 蛋白（trimeric GTP-binding regulatory protein）是三聚体 GTP 结合蛋白，由α、β和γ 三个亚基组成，α亚基结合 GDP 处于关闭状态，结合 GTP 处于开启状态。α亚基具有 GTP 酶活性，能催化所结合的 ATP 水解，恢复无活性的三聚体状态。在细胞信号转导过程中起 着分子开关的作用。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_3","modI":8,"term":"GTP 酶活化蛋白（GTPase-acivating prorein，GAP）。","def":"GTP 酶活化蛋白（GTPase-acivating protein，GAP）是一种含有 SH2 结构域，可与被活 化受体的磷酸化酪氨酸残基结合的蛋白，它的功能是增强 Ras 蛋白的 GTP 酶活性，促进 Ras 蛋白从活化状态到失活的转变，从而与信号转导相关。","kps":"","kp":"ch10_s8_42"},{"id":"ch10_term_4","modI":8,"term":"磷酸酶(phosphatase)。","def":"从蛋白质上除去磷酸基团。对于不同的底物蛋白，去磷酸化可使其激活或失活，并终止 细胞内信号转导。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_6","modI":8,"term":"钙调蛋白","def":"钙调蛋白（CaM）是一种真核细胞普遍存在的 Ca2 应答蛋白，含有 4 个结构域，每个 ＋   结构域可结合一个 Ca2 。CaM 本身无活性，它活化靶酶过程可分为两步：Ca2 与 CaM 结合 ＋                       ＋   形成活化态的 Ca2 -CaM 复合体；与靶酶结合将其活化。CaM 活化靶酶是一个受 Ca2 浓度 ＋                             ＋   控制的可逆反应。","kps":"","kp":"ch10_s8_36"}]}],"mcq":[{"id":"ch10_mcq_1","mod":"1.2   细胞内的信号分子","modI":3,"q":"下列有关气体信号分子 NO 的说法，错误的是（          ）。","o":["A．在平滑肌细胞内，L 精氨酸在 NO 合酶催化作用下生成 NO","B．NO 通过增强可溶性鸟苷酸环化酶的活性，发挥作用","C．鸟苷酸环化酶催化 GTP 生成 cGMP，cGMP 介导蛋白质的磷酸化","D．NO 通过舒张血管平滑肌治疗心绞痛，NO 也参与大脑的学习记忆生理过程"],"a":"A","e":"血管内皮细胞和神经细胞是 NO 的生成细胞，NO 再经扩散进入平滑肌细胞发挥作 用。","kp":"ch10_s3_8"},{"id":"ch10_mcq_2","mod":"4.1.1   G蛋白与跨膜信号转导","modI":8,"q":"下列不具有分子开关作用的蛋白是（            ）。","o":["A．G 蛋白","B．Ras 蛋白","C．接头蛋白","D．Rho 蛋白"],"a":"C","e":"接头蛋白在信号通路中既不能被磷酸化，也不能结合 GTP，它只起偶联作用。而 G 蛋白、Ras 蛋白和 Rho 蛋白分别在不同的信号通路中发挥了分子开关的作用，当其结合 GTP 时处于活化状态，当其结合 GDP 时处于失活状态。Rho 在整联蛋白介导的信号传递中起分 子开关的作用。","kp":"ch10_s8_41"},{"id":"ch10_mcq_3","mod":"一、信号分子","modI":1,"q":"对于由整联蛋白介导的信号传递，下列哪项说法错误？（            ）","o":["A．胞外配体主要为细胞外基质成分，如纤连蛋白等","B．整联蛋白与胞外配体的相互作用只产生一种胞内信号，即胞内 Ca2+浓度增加","C．当胞外配体与整联蛋白结合，可导致分子开关蛋白 Rho 蛋白激活","D．最终作用是与细胞增殖相关的基因被激活，细胞周期相关蛋白合成"],"a":"B","e":"整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞质基质，肌 醇第二信使的合成，胞内酪氨酸残基的磷酸化等。","kp":"ch10_s1_5"},{"id":"ch10_mcq_4","mod":"二、受体(receptor)","modI":4,"q":"下列关于信号分子的描述中，不正确的是（                ）。","o":["A．神经递质属于亲脂性信号","B．本身不具有酶的活性","C．能传递信息","D．可作为作用底物"],"a":"A","e":"神经递质属于亲水性信号分子。","kp":"ch10_s4_11"},{"id":"ch10_mcq_5","mod":"1.2   细胞内的信号分子","modI":3,"q":"动物细胞内引起储存 Ca2 释放的第二信使分子是（               ）。 ＋","o":["A．IP3","B．DAG","C．cAMP","D．cGMP"],"a":"A","e":"IP3（三磷酸肌醇）作为第二信使，从质膜扩散到细胞质，引起 Ca2 从内质网钙库 ＋   中释放出来，导致细胞内 Ca2 浓度瞬间增高，这一作用发生在几乎所有真核细胞中。 ＋","kp":"ch10_s3_8"},{"id":"ch10_mcq_6","mod":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","modI":6,"q":"表皮生长因子（EGF）的穿膜信号转导是通过（                ）实现的。","o":["A．活化酪氨酸激酶","B．活化酪氨酸磷酸酶","C．cAMP 调节途径","D．cGMP 调节途径"],"a":"A","e":"EGF 的受体分子是酪氨酸激酶受体，EGF 可以活化酪氨酸激酶受体，使其获得激 酶活性，从而传导信号。","kp":"ch10_s6_22"},{"id":"ch10_mcq_7","mod":"绪论 · 概览","modI":0,"q":"霍乱杆菌引起急性腹泻是由于（              ）。","o":["A．G 蛋白持续激活","B．G 蛋白不能被激活","C．受体封闭","D．蛋白激酶 PKC 功能异常","E．蛋白激酶 PKA 异常"],"a":"A","e":"","kp":"ch10_s0_0"},{"id":"ch10_amcq_1","mod":"三、NO信号[Ca2+→NO→cGMP→PKG]","modI":5,"q":"关于「NO信号[Ca2+→NO→cGMP→PKG]」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. NO acts only locally because it has a short half-life (about","C. 同一个细胞上不同受体应答不","D. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基"],"a":"B","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13"},{"id":"ch10_amcq_3","mod":"4.1 G protein-Cou","modI":7,"q":"关于「G protein-Cou」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. 同一个细胞上不同受体应答不","C. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","D. The receptor activation stimulated by light causes a fall rather than a rise in"],"a":"D","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27"}],"judge":[{"id":"ch10_judge_1","modI":2,"q":"细胞间的通讯就是通过细胞间形成缝隙连接，是细胞质相互沟通而实现的。（              ）","a":"错","e":"间隙连接仅仅是细胞通讯的一种方式，细胞通讯还可以通过分泌化学信号以及细胞 直接接触而实现，而且这两种方式是相对较普遍的。","kp":"ch10_s2_7"},{"id":"ch10_judge_2","modI":4,"q":"所有的受体都是跨膜蛋白质。（       ）","a":"错","e":"细胞表面的受体多为跨膜糖蛋白，但细胞内的受体如基因调控蛋白等不一定是。","kp":"ch10_s4_11"},{"id":"ch10_judge_3","modI":8,"q":"G 蛋白偶联受体被激活后，使相应的 G 蛋白解离成α、β、γ三个亚基，以进行信号传递。 （      ）","a":"错","e":"G 蛋白三聚体结合 GTP 后解离出成α亚基和βγ亚基复合物，β与γ亚基并未解离。","kp":"ch10_s8_49"},{"id":"ch10_judge_4","modI":6,"q":"激素受体都具有酪氨酸受体结构域。(       )","a":"错","e":"激素受体都具有各自激素的特异结构域。","kp":"ch10_s6_22"},{"id":"ch10_judge_5","modI":8,"q":"G 蛋白耦联的受体的 N 端结合 G 蛋白，C 端结合胞外信号。( )","a":"错","e":"G 蛋白耦联的受体的 N 端在细胞外侧结合胞外信号，C 端在细胞胞质侧。","kp":"ch10_s8_36"},{"id":"ch10_judge_6","modI":5,"q":"来源于质膜的不同信号能通过细胞内不同信号途径间的相互作用而被整合。（         ）","a":"对","e":"","kp":"ch10_s5_18"},{"id":"ch10_judge_7","modI":0,"q":"ras 是一个癌基因。（  ）","a":"错","e":"ras 是一个原癌基因，如果带有使其始终处于活化状态的突变，才会变成癌基因。","kp":"ch10_s0_0"},{"id":"ch10_judge_8","modI":0,"q":"乙酰胆碱对一个动物的不同细胞有不同的效应，而且它和不同细胞上的不同受体分子相 结合。（      ）","a":"对","e":"比如，乙酰胆碱通过结合一种 G 蛋白耦联受体而减弱心肌细胞的搏动；通过结合 另一不同的乙酰胆碱受体而刺激骨骼肌细胞的收缩。这种受体是一种配体门控离子通道。","kp":"ch10_s0_3"},{"id":"ch10_judge_9","modI":3,"q":"NO 作为信号分子，它能使细胞内的 cAMP 水平升高。（              ）","a":"错","e":"NO 释放后可以激活其受体，从而刺激生成第二信使 cGMP，cGMP 的作用是通过 cGMP 依赖的蛋白激酶 G 的活化抑制肌动-肌球蛋白复合物信号通路，导致血管平滑肌的舒 张。","kp":"ch10_s3_8"},{"id":"ch10_judge_10","modI":1,"q":"细胞外信号都是通过细胞表面受体来进行跨膜信号传递的。（                    ）","a":"错","e":"有的脂溶性的信号分子可以跨膜进入细胞与胞内受体结合。","kp":"ch10_s1_5"},{"id":"ch10_judge_11","modI":8,"q":"细胞受体与腺苷酸环化酶同在质膜上，是相互分离的在功能上相关的两种蛋白。（                        ）","a":"对","e":"","kp":"ch10_s8_49"},{"id":"ch10_ajudge_2","modI":5,"q":"NO acts only locally because it has a short half-life (about","a":"对","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13"},{"id":"ch10_ajudge_4","modI":7,"q":"The receptor activation stimulated by light causes a fall rather than a rise in","a":"对","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27"}],"fill":[{"id":"ch10_fill_1","modI":2,"q":"生物体内的化学信号分子一般可以分为______和______两类。","a":"亲脂性的信号分子；亲水性的信号分子","kp":"ch10_s2_7"},{"id":"ch10_fill_2","modI":8,"q":"由 G 蛋白偶联受体所介导的细胞信号通路主要包括 ______、______和______。","a":"cAMP 信号通路；磷脂酰肌醇信号通路；G 蛋白偶联离子通道的信号通路","kp":"ch10_s8_49"},{"id":"ch10_fill_3","modI":6,"q":"从蛋白结构看，蛋白激酶 A 是由______组成的，而蛋白激酶 C 是______组成。","a":"四个亚基；只有一条肽链","kp":"ch10_s6_22"},{"id":"ch10_fill_4","modI":3,"q":"在体内发现的第一个气体信号分子是______。","a":"NO","kp":"ch10_s3_8"},{"id":"ch10_fill_5","modI":4,"q":"根据信号转导机制和受体蛋白类型的不同，细胞表面受体可以分为______、______ 、 ______。","a":"离子通道耦联受体；G 蛋白耦联受体；酶连受体","kp":"ch10_s4_11"},{"id":"ch10_fill_6","modI":1,"q":"细胞的信号传递是______、______、______、______的______过程。","a":"多通路；多环节；多层次；高度复杂可控","kp":"ch10_s1_5"},{"id":"ch10_fill_7","modI":4,"q":"甾类激素诱导的基因活化分为两个阶段：______和______。","a":"直接活化少数特殊基因转录的初级反应阶段；初级反应的基因产物再活化其他基因产生延迟 的次级反应","kp":"ch10_s4_12"},{"id":"ch10_fill_8","modI":1,"q":"通过黏合斑由整联蛋白介导的信号传递通路有两条：______和______。","a":"由细胞表面到细胞核的信号通路；由细胞表面到细胞质核糖体的信号通路","kp":"ch10_s1_5"},{"id":"ch10_fill_9","modI":8,"q":"G 蛋白的______结构可以变化，并可以结合______使其成为关闭态。","a":"α亚基；ADP","kp":"ch10_s8_36"},{"id":"ch10_fill_10","modI":6,"q":"受体自磷酸化的结果是激活了受体的______活性，磷酸化的酪氨酸残基可被含有______ 结构域的胞内信号蛋白识别。","a":"酪氨酸蛋白激酶；SH2","kp":"ch10_s6_22"},{"id":"ch10_fill_11","modI":3,"q":"NO 在胞外极不稳定，被氧化后以______的形式存在于细胞外液中。","a":"硝酸根或亚硝酸根","kp":"ch10_s3_8"},{"id":"ch10_fill_12","modI":1,"q":"动物细胞间通讯连接的主要方式是______，植物细胞的通讯连接方式是通过______。","a":"间隙连接；胞间连丝","kp":"ch10_s1_5"},{"id":"ch10_fill_13","modI":8,"q":"Gs 的α亚基和 G 的α亚基上都有细胞毒素 ADP 核糖基化位点，但结合的毒素是不同的， 前者结合是______，后者结合的是______。","a":"百日咳毒素；霍乱毒素","kp":"ch10_s8_35"},{"id":"ch10_fill_14","modI":0,"q":"自身免疫性受体病是由于______。","a":"机体产生抗自身受体的抗体，与受体结合后使受体失去功能或改变作用方向查看答 案","kp":"ch10_s0_0"},{"id":"ch10_fill_15","modI":6,"q":"细胞内的受体具有同源性，一般由 800 个氨基酸组成，分为三个结构域，即______，______ 和______。","a":"C 端与信号分子结合部位；中部与 DNA 结合部位；N 端激活基因转录部位查看答 案","kp":"ch10_s6_22"},{"id":"ch10_fill_16","modI":8,"q":"Ras 蛋白在 RTKs 介导的信号通路中起着关键作用，具有 活性，当结合______时为活 化状态，当结合 时为失活状态。GAP 增强 Ras 的 。","a":"GTPase；GTP；GDP；失活","kp":"ch10_s8_39"},{"id":"ch10_fill_17","modI":2,"q":"细胞分泌化学信号的作用方式可分为：________、________、________；通过化学突触 传递神经信号。","a":"自分泌；内分泌；旁分泌","kp":"ch10_s2_6"}],"term":[{"id":"ch10_term_1","modI":2,"term":"细胞通讯（cell communication）。","def":"细胞通讯（cell communication）是指一个细胞发出的信号通过某种介质传递到另一细胞， 并使其产生相应的反应。细胞通讯在多细胞生物体的发生和组织的构建，协调细胞的功能， 控制细胞的生长和分裂中发挥了重要的作用。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_2","modI":8,"term":"G 蛋白（trimeric GTP-binding regulatory protein）。","def":"G 蛋白（trimeric GTP-binding regulatory protein）是三聚体 GTP 结合蛋白，由α、β和γ 三个亚基组成，α亚基结合 GDP 处于关闭状态，结合 GTP 处于开启状态。α亚基具有 GTP 酶活性，能催化所结合的 ATP 水解，恢复无活性的三聚体状态。在细胞信号转导过程中起 着分子开关的作用。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_3","modI":8,"term":"GTP 酶活化蛋白（GTPase-acivating prorein，GAP）。","def":"GTP 酶活化蛋白（GTPase-acivating protein，GAP）是一种含有 SH2 结构域，可与被活 化受体的磷酸化酪氨酸残基结合的蛋白，它的功能是增强 Ras 蛋白的 GTP 酶活性，促进 Ras 蛋白从活化状态到失活的转变，从而与信号转导相关。","kps":"","kp":"ch10_s8_42"},{"id":"ch10_term_4","modI":8,"term":"磷酸酶(phosphatase)。","def":"从蛋白质上除去磷酸基团。对于不同的底物蛋白，去磷酸化可使其激活或失活，并终止 细胞内信号转导。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_5","modI":6,"term":"离子通道耦联受体（ion-channel-coupled receptor）。","def":"离子通道耦联受体是由多亚基组成的受体一离子通道复合体，本身既有结合位点，又是 离子通道，其跨膜信号转导无需中间步骤。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_6","modI":8,"term":"钙调蛋白","def":"钙调蛋白（CaM）是一种真核细胞普遍存在的 Ca2 应答蛋白，含有 4 个结构域，每个 ＋   结构域可结合一个 Ca2 。CaM 本身无活性，它活化靶酶过程可分为两步：Ca2 与 CaM 结合 ＋                       ＋   形成活化态的 Ca2 -CaM 复合体；与靶酶结合将其活化。CaM 活化靶酶是一个受 Ca2 浓度 ＋                             ＋   控制的可逆反应。","kps":"","kp":"ch10_s8_36"},{"id":"ch10_term_7","modI":2,"term":"signal transduction","def":"signal transduction 的中文名称是信号转导。信号转导是指一个细胞发出的信息，可通过 介质传递到另一个细胞并产生相应的反应的过程，是一种复杂的系统通讯活动及协助细胞的 活动。信号转导可以实现细胞间通讯，是协调多细胞生物细胞间功能、控制细胞的生长和分 裂、组织发生与形态建成所必需的关键过程。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_8","modI":6,"term":"RTK","def":"RTK 的中文名称是受体酪氨酸激酶。受体酪氨酸激酶是一类酶联受体，既是受体，又 具有酶功能。当 RTK 与其配体结合后，两个受体在膜上二聚化，两个受体分子具有微弱的 蛋白激酶活性，当它们相互靠近后通过相互磷酸化的机制将二者自身的蛋白激酶活化，使下 游蛋白的酪氨酸残基磷酸化，从而实现信号转导的功能。所有的受体酪氨酸激酶都由三个部 分组成：具配体结合位点的胞外结构域、单次跨膜的疏水α螺旋区、具酪氨酸蛋白激酶活性 的胞内结构域。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_9","modI":2,"term":"细胞通讯","def":"细胞通讯是指一个细胞发出的信息通过介质（又称配体）传递到另一个靶细胞并与其相 应的受体相互作用，然后通过细胞信号转导产生靶细胞内一系列生理生化变化，最终表现为 靶细胞整体的生物学效应的过程。","kps":"","kp":"ch10_s2_7"}],"short":[{"id":"ch10_short_1","modI":0,"q":"简述细胞通讯的方式。","a":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","kp":"ch10_s0_1"},{"id":"ch10_short_2","modI":8,"q":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","a":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","kp":"ch10_s8_34"},{"id":"ch10_short_3","modI":0,"q":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","a":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","kp":"ch10_s0_0"},{"id":"ch10_short_4","modI":8,"q":"由哪些蛋白调控单体 G 蛋白的活性？","a":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","kp":"ch10_s8_41"},{"id":"ch10_short_5","modI":4,"q":"霍乱毒素通过什么机制引起腹泻的？","a":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","kp":"ch10_s4_11"},{"id":"ch10_short_6","modI":0,"q":"简述日咳产生的细胞学原因。","a":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","kp":"ch10_s0_0"},{"id":"ch10_short_7","modI":8,"q":"简述 NO 的作用机制。","a":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","kp":"ch10_s8_34"},{"id":"ch10_short_8","modI":8,"q":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","a":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","kp":"ch10_s8_49"},{"id":"ch10_short_9","modI":8,"q":"比较植物中的信号传导途径和动物中的信号传导途径。","a":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","kp":"ch10_s8_39"},{"id":"ch10_short_10","modI":8,"q":"列表比较 PKA 与 PKC 信号转导系统。","a":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","kp":"ch10_s8_34"},{"id":"ch10_short_11","modI":1,"q":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","a":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","kp":"ch10_s1_5"},{"id":"ch10_short_12","modI":0,"q":"细胞信号转导的复杂性主要表现在哪几个方面？","a":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","kp":"ch10_s0_0"},{"id":"ch10_short_13","modI":0,"q":"试述参与细胞信号转导的细胞膜受体的种类与特点。","a":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","kp":"ch10_s0_0"},{"id":"ch10_short_14","modI":4,"q":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","a":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","kp":"ch10_s4_11"}],"calc":[{"id":"ch10_calc_1","modI":6,"q":"试述细胞接受化学信号后调节基因表达的途径？","a":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","kp":"ch10_s6_23"},{"id":"ch10_calc_2","modI":7,"q":"从受体的角度解读家族性高胆固醇血症的发病机理。","a":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","kp":"ch10_s7_27"},{"id":"ch10_calc_3","modI":8,"q":"何谓信号转导中的分子开关机制？举例说明。","a":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","kp":"ch10_s8_34"},{"id":"ch10_calc_4","modI":8,"q":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","a":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","kp":"ch10_s8_49"},{"id":"ch10_calc_5","modI":4,"q":"图解细胞表面受体调节基因表达的信号通路。","a":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","kp":"ch10_s4_11"}],"appcards":[{"front":"简述细胞通讯的方式。","back":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","back":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","back":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"由哪些蛋白调控单体 G 蛋白的活性？","back":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"霍乱毒素通过什么机制引起腹泻的？","back":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","mod":4,"modName":"二、受体(receptor)","points":""},{"front":"简述日咳产生的细胞学原因。","back":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"简述 NO 的作用机制。","back":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","back":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"比较植物中的信号传导途径和动物中的信号传导途径。","back":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"列表比较 PKA 与 PKC 信号转导系统。","back":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","back":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","mod":1,"modName":"一、信号分子","points":""},{"front":"细胞信号转导的复杂性主要表现在哪几个方面？","back":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"试述参与细胞信号转导的细胞膜受体的种类与特点。","back":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","back":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","mod":4,"modName":"二、受体(receptor)","points":""},{"front":"试述细胞接受化学信号后调节基因表达的途径？","back":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","mod":6,"modName":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","points":""},{"front":"从受体的角度解读家族性高胆固醇血症的发病机理。","back":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","mod":7,"modName":"4.1 G protein-Cou","points":""},{"front":"何谓信号转导中的分子开关机制？举例说明。","back":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","back":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"图解细胞表面受体调节基因表达的信号通路。","back":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","mod":4,"modName":"二、受体(receptor)","points":""}]};